package es.riegocerca.maps; import android.app.Activity; import android.content.Intent; import android.net.Uri; import android.webkit.JavascriptInterface; import org.json.JSONArray; public class MapsBridge{private final Activity a;MapsBridge(Activity a){this.a=a;}@JavascriptInterface public void navigate(String c){open("https://www.google.com/maps/dir/?api=1&destination="+Uri.encode(c));}@JavascriptInterface public void openMulti(String j){try{JSONArray p=new JSONArray(j);if(p.length()>0)navigate(p.getString(p.length()-1));}catch(Exception e){}}private void open(String u){a.runOnUiThread(()->{try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){}});}}
